cd /app; python3 - <<'EOF'
p='src/game/client/components/players.cpp'
s=open(p).read()
old_start=s.index('	// Calculate hook coll line position')
old_end=s.index('	vLineSegments.emplace_back(InitPos, FinishPos);\n\n	if(AlwaysRenderHookColl')
new='''	// Calculate hook coll line position, mirroring the hook physics in CCharacterCore::Tick
	const CTuningParams &Tuning = GameClient()->m_aClients[ClientId].m_Predicted.m_Tuning;
	const float HookSpeed = Tuning.m_HookFireSpeed;
	if(HookSpeed <= 0.0f)
		return;

	const float HookLength = Tuning.m_HookLength;
	const bool PlayerHooking = Tuning.m_PlayerHooking;

	const float LineOffset = CCharacterCore::PhysicalSize() * 1.5f;
	const vec2 TargetDirection = Direction;
	vec2 InitPos = Position; // start of the currently drawn segment
	vec2 HookBase = Position; // base used for the hook length check
	vec2 FinishPos = InitPos + Direction * HookLength;

	ColorRGBA HookCollColor = color_cast<ColorRGBA>(ColorHSLA(g_Config.m_ClHookCollColorNoColl));

	vec2 OldPos = InitPos + Direction * LineOffset;
	vec2 NewPos = OldPos;

	bool DoBreak = false;
	std::vector<IGraphics::CLineItem> vLineSegments;
	do
	{
		OldPos = NewPos;
		NewPos = OldPos + Direction * HookSpeed;

		if(distance(HookBase, NewPos) > HookLength)
		{
			NewPos = HookBase + normalize(NewPos - HookBase) * HookLength;
			DoBreak = true;
		}

		int Tele;
		int Hit = Collision()->IntersectLineTeleHook(OldPos, NewPos, &FinishPos, nullptr, &Tele);

		// players are only checked along the path the hook actually travels (up to the tile it hits)
		if(PlayerHooking && ClientId >= 0 && GameClient()->IntersectCharacter(OldPos, FinishPos, FinishPos, ClientId) != -1)
		{
			HookCollColor = color_cast<ColorRGBA>(ColorHSLA(g_Config.m_ClHookCollColorTeeColl));
			break;
		}

		if(!DoBreak && Hit == TILE_TELEINHOOK)
		{
			if(Collision()->TeleOuts(Tele - 1).size() != 1)
			{
				Hit = Collision()->IntersectLineTeleHook(OldPos, NewPos, &FinishPos, nullptr);
			}
			else
			{
				vLineSegments.emplace_back(InitPos, FinishPos);
				InitPos = Collision()->TeleOuts(Tele - 1)[0];
				Direction = TargetDirection;
				HookBase = NewPos = InitPos + Direction * LineOffset;
				FinishPos = NewPos;
				continue;
			}
		}

		if(Hit && Hit != TILE_TELEINHOOK)
		{
			if(Hit != TILE_NOHOOK)
				HookCollColor = color_cast<ColorRGBA>(ColorHSLA(g_Config.m_ClHookCollColorHookableColl));
			break;
		}

		NewPos.x = round_to_int(NewPos.x);
		NewPos.y = round_to_int(NewPos.y);

		if(OldPos == NewPos)
			break;

		Direction.x = round_to_int(Direction.x * 256.0f) / 256.0f;
		Direction.y = round_to_int(Direction.y * 256.0f) / 256.0f;
	} while(!DoBreak);

'''
s=s[:old_start]+new+s[old_end:]
s=s.replace('''		const vec2 PerpToAngle = direction(pi / 2.0f - angle(Direction)) * GameClient()->m_Camera.m_Zoom;''','''		const vec2 PerpToAngle = normalize(vec2(-TargetDirection.y, TargetDirection.x)) * GameClient()->m_Camera.m_Zoom;''')
open(p,'w').write(s)

p='src/game/client/gameclient.cpp'
s=open(p).read()
s=s.replace('''		if(!Data.m_Active)
			continue;

		CNetObj_Character Prev = m_Snap''','''		if(!Data.m_Active || !m_Snap.m_aCharacters[i].m_Active)
			continue;

		CNetObj_Character Prev = m_Snap''')
s=s.replace('''			if(distance(Position, ClosestPoint) < CCharacterCore::PhysicalSize() / 2.0f + 2.0f)''','''			if(distance(Position, ClosestPoint) < CCharacterCore::PhysicalSize() + 2.0f)''')
open(p,'w').write(s)
EOF
